 37	// Sample is a self-test entry for a Rule. The runner asserts whether the
 38	// rule's regex matching `Input` matches the `Redacted` expectation.
 39	type Sample struct {
 40		Input    string `json:"input"    yaml:"input"`
 41		Redacted bool   `json:"redacted" yaml:"redacted"`
 42	}
