346	// EnsureRedactionConfigured loads redaction settings and configures the
347	// redact package: PII detection (opt-in), inline custom_secrets, and rule
348	// packs auto-discovered from .entire/redactors/.
349	//
350	// Must be called at each process entry point before checkpoint writes.
351	func EnsureRedactionConfigured() {
352		initRedactionOnce.Do(func() {
353			ctx := context.Background()
354			s, err := settings.Load(ctx)
355			if err != nil {
356				logCtx := logging.WithComponent(ctx, "redaction")
357				logging.Warn(logCtx, "failed to load settings for redaction", slog.String("error", err.Error()))
358				return
359			}
360	
361			// 1. PII (existing, opt-in).
362			if s.Redaction != nil && s.Redaction.PII != nil && s.Redaction.PII.Enabled {
363				pii := s.Redaction.PII
364				cfg := redact.PIIConfig{
365					Enabled:        true,
366					Categories:     make(map[redact.PIICategory]bool),
367					CustomPatterns: pii.CustomPatterns,
368				}
369				cfg.Categories[redact.PIIEmail] = pii.Email == nil || *pii.Email
370				cfg.Categories[redact.PIIPhone] = pii.Phone == nil || *pii.Phone
371				cfg.Categories[redact.PIIAddress] = pii.Address != nil && *pii.Address
372				redact.ConfigurePII(cfg)
373			}
374	
375			// 2. Inline + pack-based custom rules.
376			var inline map[string]string
377			if s.Redaction != nil {
378				inline = s.Redaction.CustomSecrets
379			}
380			packsDir, perr := paths.AbsPath(ctx, filepath.Join(paths.EntireDir, "redactors"))
381			if perr != nil {
382				logCtx := logging.WithComponent(ctx, "redaction")
383				logging.Warn(logCtx, "failed to resolve redactors path", slog.String("error", perr.Error()))
384				packsDir = filepath.Join(paths.EntireDir, "redactors")
385			}
386			packs, lerr := redact.LoadPacks(packsDir)
387			if lerr != nil {
388				logCtx := logging.WithComponent(ctx, "redaction")
389				logging.Warn(logCtx, "failed to load redactor packs", slog.String("error", lerr.Error()))
390			}
391			if len(inline) > 0 || len(packs) > 0 {
392				redact.ConfigureCustomRules(redact.CustomRulesConfig{
393					Inline: inline,
394					Packs:  packs,
395				})
396			}
397		})
398	}
