    44	// ParsePack decodes a single pack file. sourcePath is used both to pick
    45	// the encoding (YAML by default; JSON only when the extension is .json)
    46	// and to enforce that the pack's `name` matches the filename stem.
    47	func ParsePack(data []byte, sourcePath string) (*Pack, error) {
    48		var pack Pack
    49		switch strings.ToLower(filepath.Ext(sourcePath)) {
    50		case ".json":
    51			if err := json.Unmarshal(data, &pack); err != nil {
    52				return nil, fmt.Errorf("parse %s: %w", sourcePath, err)
    53			}
    54		default:
    55			if err := yaml.Unmarshal(data, &pack); err != nil {
    56				return nil, fmt.Errorf("parse %s: %w", sourcePath, err)
    57			}
    58		}
